import { Link, useRouterState } from "@tanstack/react-router";
import { cn } from "@/lib/utils";

interface Tab {
  label: string;
  to: string;
  /** The search params pattern that marks this tab as active. Defaults to exact path match. */
  matchPath?: string;
}

interface TabNavProps {
  pelatihanId: string;
}

/**
 * Segmented tab navigator for the E-Learning detail page.
 * Matches the COMPONENT BUTTON E-LEARNING Figma component.
 * Active tab has blue bottom border + blue text; others are muted.
 */
export function TabNav({ pelatihanId }: TabNavProps) {
  const base = `/back-office/pelatihan/${pelatihanId}`;

  const tabs: Tab[] = [
    { label: "Overview", to: `${base}/overview` },
    { label: "Materi", to: `${base}/materi` },
    { label: "Quiz & Post Test", to: `${base}/quiz` },
    { label: "Peserta", to: `${base}/peserta` },
    { label: "Penilaian Ujian", to: `${base}/penilaian` },
    { label: "Sertifikat", to: `${base}/sertifikat` },
  ];

  const pathname = useRouterState({ select: (s) => s.location.pathname });

  return (
    <div className="overflow-hidden rounded-xl border border-[#E2E8F0] bg-white shadow-[0px_1px_2px_0px_rgba(15,23,42,0.04),0px_2px_6px_0px_rgba(15,23,42,0.06)]">
      <div className="flex items-stretch overflow-x-auto">
        {tabs.map((tab, i) => {
          const isActive =
            pathname === tab.to || pathname.startsWith(`${tab.to}/`);
          const isFirst = i === 0;
          const isLast = i === tabs.length - 1;

          return (
            <Link
              key={tab.to}
              to={tab.to}
              className={cn(
                "relative flex min-w-[128px] items-center justify-center border-b-2 px-8 py-[15px] text-sm font-semibold whitespace-nowrap transition-all duration-200",
                // Border separators between tabs
                i > 0 && "border-l border-l-[#E2E8F0]",
                isFirst && "rounded-tl-xl",
                isLast && "rounded-tr-xl",
                isActive
                  ? "border-b-[#1061D6] bg-blue-50/50 text-[#1061D6]"
                  : "border-b-transparent text-[#768094] hover:bg-slate-50/50 hover:text-[#4D4D4D]",
              )}
            >
              {tab.label}
            </Link>
          );
        })}
      </div>
    </div>
  );
}

